  const notes=truth.clips.find(c=>c.clipId===residual.clipId).notes.filter(n=>n.timeMs>=1380&&n.timeMs<27780);
  for(const r of residual.rows)r.nearestAnyPitchPhysicalDistanceMs=Math.min(...notes.map(n=>Math.abs(n.timeMs-r.performanceTimeMs)));
  residual.nearestAnyPitchPhysicalDistanceMs=describe(residual.rows.map(r=>r.nearestAnyPitchPhysicalDistanceMs));
 }
 extras.push({id:item.id,split:item.split,physicalClipCount:row.naturalResidual.length,residualRows:row.naturalResidual,
  totalResiduals:row.naturalResidual.reduce((n,r)=>n+r.residualCount,0),
  falsePositiveResidualsPerMinute:row.naturalResidual.reduce((n,r)=>n+r.residualCount,0)/(row.naturalResidual.length*26400/60000),
  counterfactualExtra:{original:{precision:row.original.rates.extraPrecision,recall:row.original.rates.extraRecall},bounded:{precision:row.bounded.rates.extraPrecision,recall:row.bounded.rates.extraRecall}},
  baselineFalseTargetExtraBuckets:row.baselineFalseTargetExtraBuckets??null});
 const original=await load(OLD_ROOT+'/metrics/'+(item.split==='EVALUATION'?'evaluation':'geometry')+'/'+item.id+'.json');
 const changes=new Map(row.pairedScenarioDifferences.pairedScenarioDifferences.map(x=>[x.id,x]));
 const classes={};
 for(const k of ['CORRECT','MISSING','WRONG','INCOMPLETE_CHORD','EXTRA']){
  const matched=original.targetRows.filter(r=>r.truth===k&&r.latencyMs!==null&&changes.get(r.id)?.latencyDeltaMs!==null);
  classes[k]={basis:'Same fixed original truth target under both policies, regardless of the predicted class; EXTRA requires finite availability under both, missing detections retained in correctness counts.',
   pairedCount:matched.length,totalOriginalTargets:original.targetRows.filter(r=>r.truth===k).length,
   original:latencySummary(matched.map(r=>r.latencyMs)),bounded:latencySummary(matched.map(r=>r.latencyMs+changes.get(r.id).latencyDeltaMs)),
   deltaMs:describe(matched.map(r=>changes.get(r.id).latencyDeltaMs))};
 }
 paired.push({id:item.id,split:item.split,classes});
}
await atomicJson(reportDir+'/phase9g_xc2_r1_natural_residual_and_paired_latency_2026-10-16.json',{phase:PHASE,classification:'POST_XC2_DIAGNOSTIC_ONLY_NOT_FRESH_EVALUATION',
 definition:'Each physical clip once per configuration; 50ms pitch-aware one-to-one acoustic residual, denominator26.4seconds per clip. Not scenario-weighted natural-prevalence inference.',
 duplicateDefinition:'Same-pitch unmatched event within50ms of a physical onset already matched by another prediction.',
 falseTargetExtraBucketCaution:'Deterministic ordered descriptive buckets, not verified causal diagnoses; 184 baseline false target extras are scenario-expanded, not184 independent physical errors.',
 rows:extras,pairedFixedTargetLatency:paired,generatorSource:process._eval});
const detail=[];
for(const r of runtime.rows){
 if(await fileSha(r.path)!==r.sha256)throw Error('RUNTIME_MUTATION');
 const x=await load(r.path);validateArtifactDigest(x);
 if(x.runtime.identity.ortVersion!=='1.20.1'||x.runtime.identity.sessionLoadCount!==1||x.runtime.identity.actualSessionRunCount!==x.runtime.rows.length+3||x.browser.launchArgsIncludeUnsafeWebGpu||x.browser.headed!==true)throw Error('RUNTIME_IDENTITY');
 let episode=[],episodes=[];
 for(const t of x.runtime.rows){if(t.queueDelayMs>8)episode.push(t);else if(episode.length){episodes.push(episode);episode=[];}}
 if(episode.length)episodes.push(episode);
 detail.push({...r,browser:x.browser,adapter:x.adapter,identity:x.runtime.identity,warmup:x.runtime.warmup,
  schedulingDelayMs:describe(x.runtime.rows.map(y=>y.schedulingDelayMs)),
  earlyTimerCount:x.runtime.rows.filter(y=>y.schedulingDelayMs<0).length,
  earlyTimerMinimumMs:Math.min(...x.runtime.rows.map(y=>y.schedulingDelayMs)),
  runtimeRows:x.runtime.rows,summary:x.summary,postCaptureBrowserSerializationAndNodeIpcMs:x.postCaptureBrowserSerializationAndNodeIpcMs,
  postCaptureReceiptAssemblyMs:x.postCaptureReceiptAssemblyMs,
  artifactExportSerializationMs:x.artifactExportSerializationMs,
  queueEpisodesAboveFrozen8msJitterAllowance:episodes.map(e=>({windows:e.length,start:e[0].scheduledReadyTimestamp,end:e.at(-1).publicationFinishTimestamp,durationMs:e.at(-1).publicationFinishTimestamp-e[0].scheduledReadyTimestamp,maxQueueMs:Math.max(...e.map(y=>y.queueDelayMs))})),
  verdictCount:x.runtime.boundedFinalization.verdicts.length});
}
if(detail.length!==27)throw Error('INCOMPLETE_RUNTIME');
const groups=freeze.configurations.map(c=>{
 const rows=detail.filter(r=>r.config===c.id),warm=rows.flatMap(r=>r.runtimeRows.slice(3).filter(t=>!t.shiftedFinalWindow));
 return {configuration:c,sessionCount:rows.length,boundedQueuePassCount:rows.filter(r=>r.summary.backlog.noSustainedBacklog).length,
  sessionP95ProcessingMs:rows.map(r=>({repeat:r.repeat,clipId:r.clipId,p95:r.summary.productProcessingMs.p95,backlog:r.summary.backlog})),
  pooledDescriptive:{pureOrtMs:describe(warm.map(t=>t.ortSessionRunDurationMs)),resamplerMs:describe(warm.map(t=>t.resamplerMs)),decoderMs:describe(warm.map(t=>t.decoderMs)),finalizerCpuMs:describe(warm.map(t=>t.finalizerCpuMs)),productProcessingMs:describe(warm.map(t=>t.processingMs))},
  globalOrderPositionCounts:[0,1,2].map(p=>freeze.runtimeOrder.filter((r,i)=>r.config===c.id&&i%3===p).length)};
});
await atomicJson(reportDir+'/phase9g_xc2_r1_causal_runtime_receipts_2026-10-16.json',{phase:PHASE,groups,rows:detail,
 totalSessions:detail.length,totalTimedWindows:detail.reduce((n,r)=>n+r.runtimeRows.length,0),totalActualSessionRuns:detail.reduce((n,r)=>n+r.identity.actualSessionRunCount,0),
 interpretation:'Frozen bounded queue rule is retained, including max-depth transient failures; not proof of infinite-stream instability. Nominal source readiness, actual timer receipt and receive-to-start queue are separately retained.',
 coldAndWarm:'Three explicit warmups; first3timed rows fenced for warm service, all full rows used for queue.',
 confounds:'Old and new sessions are not a contemporaneous harness A/B. Changed pure ORT timing cannot be causally attributed to removing artifact persistence. No thermal/power/GPU-clock cause measured.',
 timerLimit:'setTimeout can fire sub-millisecond early; raw negative scheduling rows retained. This is source-time causal engineering simulation, not sample-accurate device capture or a hard real-time claim.'});
const witness=await load(ROOT+'/bounded_witness_manifest.json');
for(const w of witness.rows)if(await fileSha(w.path)!==w.sha256)throw Error('WITNESS_MUTATION');
await atomicJson(reportDir+'/phase9g_xc2_r1_bounded_witness_manifest_2026-10-16.json',witness);
const baselineWitness=witness.rows.find(r=>r.split==='EVALUATION'&&r.id==='LINEAR_A_600_220');
const vs=JSON.parse(gunzipSync(await readFile(baselineWitness.path)));
const byId=new Map(vs.map(v=>[v.scenarioId+':'+v.id,v]));
const baselineOld=await load(OLD_ROOT+'/metrics/evaluation/LINEAR_A_600_220.json');
const confusion={},changed=[];
for(const target of baselineOld.targetRows){
 if(target.truth==='EXTRA')continue;
 const v=byId.get(target.id);if(!v)throw Error('MISSING_WITNESS_TARGET');
 const key=target.truth+' -> '+v.verdict;confusion[key]=(confusion[key]??0)+1;
 if(target.predicted!==v.verdict)changed.push({targetId:target.id,truth:target.truth,original:target.predicted,bounded:v.verdict,witness:v.witness,evidenceObservationIds:v.evidenceObservationIds});
}
const {createJiti}=createRequire(import.meta.url)(path.join(RUNTIME_NODE_MODULES,'jiti'));
const cap=createJiti(import.meta.url)(path.join(REPO_ROOT,'apps/customer-web/src/lib/practice/input-capability.ts'));
const capabilities=cap.evaluatePracticeInputCapabilities();
capabilities.microphoneCapture={supported:true,status:'AVAILABLE'};
const productGuards=Object.fromEntries(['CONTINUOUS_PLAY','STEP_BY_STEP'].map(mode=>[mode,cap.getSelectedMicrophoneCapability(capabilities,mode)]));
if(Object.values(productGuards).some(x=>x.supported))throw Error('PRODUCTION_MIC_ENABLED');
