 originalSevenIds:(await load(reportDir+'/phase9g_xc2_product_verdict_latency_final_2026-10-16.json')).ort120Main.paretoIds,
 runtime:groups.map(g=>({configuration:g.configuration.id,boundedQueuePassCount:g.boundedQueuePassCount,sessions:g.sessionCount,pooledP95:g.pooledDescriptive.productProcessingMs.p95})),
