 semanticHorizon:{strikeMs:250,groupMs:'250 + within-group span',extraWorstBoundMs:520,observedMaxExtraHorizonMs:Math.max(...witness.rows.map(r=>r.maxExtraDirectHorizonMs))},
 baselineNaturalResidualCountEvaluation:extras.find(r=>r.id==='LINEAR_A_600_220'&&r.split==='EVALUATION').totalResiduals,
 productionCapabilityExecutableGuard:productGuards,
 preserved:{F5:'NO_CLEAR_SCIENTIFIC_ACOUSTIC_WINNER',R4:'ROBUST_CADENCE_SUSTAINABLE; ROBUST_20_PERCENT_HEADROOM_FAIL; ROBUST_PRODUCT_LATENCY_READINESS=NOT_YET_QUALIFIED',phase9gB:'STATISTICAL_TIE',winner:null,viennaP15P22InferenceIncrease:0,productionMicrophone:false,d4:false,productionWinner:null,practiceWebSocket:false,backendPracticeInference:false,serverAcousticInference:false,scoreFollowing:false},
 productLatencySlo:'PRODUCT_LATENCY_SLO_NOT_YET_FROZEN',commercialQualificationStatus:'NOT_PERFORMED',
 recommendation:'Review closed-group WRONG preemption and bounded-policy assignment tradeoffs before any production-ledger migration. Prospectively capture independent-score natural timing cases; no such capture/optimization performed here.'};
await atomicJson(reportDir+'/phase9g_xc2_r1_evidence_interpretation_2026-10-16.json',interpretation);
for(const [input,name]of [['browser_resampler_parity.json','browser_streaming_resampler_parity'],['test_execution_receipts.json','test_execution_receipts'],['existing_runtime_queue_decomposition.json','existing_runtime_queue_decomposition'],['preparation.json','audio_and_fir_identity'],['github_pre_evidence.json','github_pre_evidence']]){
 await atomicJson(reportDir+'/phase9g_xc2_r1_'+name+'_2026-10-16.json',await load(ROOT+'/'+input));
}
const finalPath=reportDir+'/phase9g_xc2_r1_bounded_runtime_final_2026-10-16.json',final=await load(finalPath);
final.postGenerationInterpretation={reason:'Broaden report interpretation beyond the three zero critical-accept counters; no scientific implementation/policy or predictions changed.',receipt:reportDir+'/phase9g_xc2_r1_evidence_interpretation_2026-10-16.json',receiptSha256:await fileSha(reportDir+'/phase9g_xc2_r1_evidence_interpretation_2026-10-16.json'),originalGeneratorCriticalOnlyClassification:final.conclusions.boundedFinalization};
final.conclusions.boundedFinalization='BOUNDED_FINALIZATION_HAS_SAFETY_TRADEOFF';
final.additionalEvidence=['natural_residual_and_paired_latency','causal_runtime_receipts','bounded_witness_manifest','browser_streaming_resampler_parity','test_execution_receipts','existing_runtime_queue_decomposition','audio_and_fir_identity','github_pre_evidence'].map(n=>reportDir+'/phase9g_xc2_r1_'+n+'_2026-10-16.json');
final.github=await load(ROOT+'/github_pre_evidence.json');
await writeFile(finalPath,JSON.stringify(final,null,2)+'\n');
await atomicJson(ROOT+'/post_generation_evidence_materialization.json',{phase:PHASE,generatorSource:process._eval,generatedFinalReportSha256:await fileSha(finalPath),classification:'READ_ONLY_EVIDENCE_PROJECTION_NO_POLICY_OR_INFERENCE_IMPLEMENTATION_CHANGE'});
console.log(JSON.stringify({groups:interpretation.runtime,confusion,changedCases:changed.length,verdicts:witness.totalVerdicts}));
